"""Feature flags for gating in-progress work behind environment variables.

Temporary developer scaffolding for trunk-based development: work that
isn't finished can still merge to `main`, gated behind a flag that
defaults to `False` everywhere except where an engineer opts in via an
environment variable. Add a flag when a feature starts; remove it — and
every branch that checks it — in the same PR that ships the feature. A
flag that outlives its feature is debt.

**Not the same as `rasa.utils.beta`.** `ensure_beta_feature_is_enabled`
gates released, customer-facing, opt-in functionality permanently, with
legal/beta-terms messaging. This module gates unfinished, internal-only
code silently and temporarily. If the gate should outlive the PR that
adds it, it's a beta feature, not a feature flag.

Prefer `make add-feature-flag NAME=<NAME>` over editing this file by hand —
see AGENTS.md ("Repo conventions" > "Feature flags").
"""

from __future__ import annotations

from enum import Enum

from rasa.utils.common import get_bool_env_variable

ENV_VAR_PREFIX = "RASA_FEATURE_FLAG_"


class FeatureFlag(str, Enum):
    """Registry of known, in-progress feature flags.

    Add/remove members via `make add-feature-flag`/`remove-feature-flag`,
    not by hand.
    """

    # make-feature-flag:start
    # Example: MY_EXAMPLE_FLAG = "MY_EXAMPLE_FLAG"
    # make-feature-flag:end


def is_enabled(flag: FeatureFlag) -> bool:
    """Check whether a feature flag is enabled.

    Checks the `RASA_FEATURE_FLAG_<NAME>` environment variable; the flag
    defaults to `False` if the variable is unset.

    Args:
        flag: The feature flag to check.

    Returns:
        `True` if the flag is enabled, `False` otherwise.
    """
    return get_bool_env_variable(
        f"{ENV_VAR_PREFIX}{flag.value}", default_variable_value=False
    )
